def feature_counts_by_module():
    from collections import defaultdict
    totals = defaultdict(int)
    done = defaultdict(int)
    for f in FEATURES:
        mod = f[1]
        totals[mod] += 1
        if f[9] == "Completed" or f[10] == "Fully Implemented":
            # count completed features by Status Completed
            pass
        if f[9] == "Completed":
            done[mod] += 1
    return {m: (totals[m], done[m]) for m in totals}


