def feature_qa_columns(feat: tuple) -> tuple[str, str, str, str, str]:
    """Return (route, how_it_works, role, credit_cost, blocking_bugs)."""
    fid, module, name, desc = feat[0], feat[1], feat[2], feat[3]
    route = FEATURE_ROUTE_OVERRIDES.get(fid, MODULE_DEFAULT_ROUTE.get(module, "/app"))
    how = FEATURE_HOW_OVERRIDES.get(
        fid,
        f"Open {route}. Exercise '{name}' ({desc}). Confirm happy path for intended role; note plan gates and credit toasts.",
    )
    role = FEATURE_ROLE_OVERRIDES.get(fid, "Free+" if module != "Admin Portal" and module != "Marketing Site" else ("Admin" if module == "Admin Portal" else "Guest"))
    if module == "Marketing Site":
        role = "Guest"
    credit = FEATURE_CREDIT_OVERRIDES.get(fid, "0 / N/A")
    blocking = FEATURE_BLOCKING_OVERRIDES.get(fid, "")
    return route, how, role, credit, blocking


